import { QueryClient } from '@tanstack/react-query';
import { createRouter } from '@tanstack/react-router';
import { routeTree } from './routeTree.gen.js';

// TanStack Query owns the session truth (AD-014) — the queryClient goes
// into the router context so _private/route.tsx (beforeLoad) calls
// ensureQueryData(sessionQuery) without needing Zustand.
export const queryClient = new QueryClient();

// AD-030: routeTree generated by @tanstack/router-plugin (createFileRoute in
// each route file) — no manual addChildren composition here.
export const router = createRouter({ routeTree, context: { queryClient } });

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}
